#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <omp.h>  /* Added for optional OpenMP parallelization */

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "doitgen.h"


/* Array initialization.
 *
 * Optimizations:
 *  - Use restrict-qualified local pointers to help the compiler with aliasing.
 *  - Precompute i*j term used inside the innermost loop.
 *  - Optionally parallelize the initialization with OpenMP; each thread writes
 *    to disjoint array elements, so there are no data races.
 */
static
void init_array(int nr, int nq, int np,
		DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np))
{
  int i, j, k;

  /* Local restrict-qualified views improve vectorization and alias analysis. */
  DATA_TYPE (*restrict A_)[nq][np] = A;
  DATA_TYPE (*restrict C4_)[np]    = C4;

  /* Initialize A. */
#pragma omp parallel for private(i,j,k) collapse(2) schedule(static)
  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
    {
      int ij = i * j;  /* hoist common sub-expression out of k-loop */
      for (k = 0; k < np; k++)
        A_[i][j][k] = (DATA_TYPE) ((ij + k) % np) / np;
    }

  /* Initialize C4. */
#pragma omp parallel for private(i,j) collapse(2) schedule(static)
  for (i = 0; i < np; i++)
    for (j = 0; j < np; j++)
      C4_[i][j] = (DATA_TYPE) ((i * j) % np) / np;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nr, int nq, int np,
		 DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np))
{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++) {
	if ((i*nq*np+j*np+k) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Original computation for a given (r,q):
 *   sum[p] = 0;
 *   for s:
 *     sum[p] += A[r][q][s] * C4[s][p];
 *   A[r][q][p] = sum[p];
 *
 * This is a row-vector (A[r][q][:]) times matrix (C4) product.
 *
 * Optimizations applied:
 *  - Use restrict-qualified local pointers for better alias analysis.
 *  - Restructure the (p,s) loops into an "outer product" form:
 *        for p: sum[p] = 0;
 *        for s:
 *          a = A[r][q][s];
 *          for p:
 *            sum[p] += a * C4[s][p];
 *    For each fixed p, the sequence of updates over s is unchanged
 *    (s still increases from 0 to NP-1), so floating-point accumulation
 *    order per output element is preserved.
 *  - Parallelize across (r,q) with OpenMP; each (r,q) pair is independent.
 *    A thread-private temporary buffer is used for accumulation to
 *    avoid data races.
 *  - To preserve the observable behavior of the original program with
 *    respect to the 'sum' array, we copy the final updated row
 *    A[_PB_NR-1][_PB_NQ-1][:] into 'sum' after the parallel region.
 */
void kernel_doitgen[[gnu::flatten, gnu::noinline]](int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

  /* Local restrict-qualified aliases to assist vectorization. */
  DATA_TYPE (*restrict A_)[nq][np] = A;
  DATA_TYPE (*restrict C4_)[np]    = C4;
  DATA_TYPE *restrict sum_global   = sum;

#pragma scop
  /* Parallel region over (r,q). Each thread owns its private accumulation
   * buffer 'sum_local', so there are no data races. */
#pragma omp parallel private(r,q,p,s)
  {
    /* Thread-private temporary buffer, reused for all (r,q) handled
     * by this thread. Size is 'np', identical to the original 'sum'. */
    DATA_TYPE sum_local[np];

#pragma omp for collapse(2) schedule(static)
    for (r = 0; r < _PB_NR; r++)
      for (q = 0; q < _PB_NQ; q++)
      {
        /* Initialize accumulation buffer. */
        for (p = 0; p < _PB_NP; p++)
          sum_local[p] = SCALAR_VAL(0.0);

        /* Outer-product style computation:
         *   sum_local[p] += A_[r][q][s] * C4_[s][p]
         * Access to C4_ is now in row-major (contiguous) order.
         */
        for (s = 0; s < _PB_NP; s++)
        {
          DATA_TYPE a_rqs = A_[r][q][s];
          const DATA_TYPE *restrict c4_row = C4_[s];

          /* Encourage the compiler to vectorize the inner loop. */
#pragma GCC ivdep
          for (p = 0; p < _PB_NP; p++)
          {
            sum_local[p] += a_rqs * c4_row[p];
          }
        }

        /* Write back the result for this (r,q) pair. */
        DATA_TYPE *restrict a_row = A_[r][q];
        for (p = 0; p < _PB_NP; p++)
          a_row[p] = sum_local[p];
      } /* end for q */
  } /* end parallel region */

  /* Preserve the final contents of 'sum' as in the original kernel.
   * Originally, after the loops, 'sum[p]' contains the values computed
   * for the last (r,q) pair: A[_PB_NR-1][_PB_NQ-1][p].
   * We reproduce this by explicitly copying that final row. */
  {
    int r_last = _PB_NR - 1;
    int q_last = _PB_NQ - 1;
    for (p = 0; p < _PB_NP; p++)
      sum_global[p] = A_[r_last][q_last][p];
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int nr = NR;
  int nq = NQ;
  int np = NP;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A,DATA_TYPE,NR,NQ,NP,nr,nq,np);
  POLYBENCH_1D_ARRAY_DECL(sum,DATA_TYPE,NP,np);
  POLYBENCH_2D_ARRAY_DECL(C4,DATA_TYPE,NP,NP,np,np);

  /* Initialize array(s). */
  init_array (nr, nq, np,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(C4));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_doitgen (nr, nq, np,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(C4),
		  POLYBENCH_ARRAY(sum));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nr, nq, np,  POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(sum);
  POLYBENCH_FREE_ARRAY(C4);

  return 0;
}
