/* doitgen.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "doitgen.h"


/* Array initialization.
 *
 * Optimizations:
 *  - Keep innermost dimension contiguous in memory (k and j loops).
 *  - Replace expensive modulus in the innermost loops with an
 *    increment-and-wrap scheme to avoid repeated `%` operations.
 *  - Use local restrict-qualified pointers for better aliasing
 *    information (helps vectorization).
 */
static
void init_array(int nr, int nq, int np,
		DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np))
{
  int i, j, k;

  /* Create local restrict-qualified views of the arrays.
   * Types use the runtime sizes (nr, nq, np) as VLA dimensions, which
   * match the actual allocations in main().
   */
  DATA_TYPE (*restrict A_)[nq][np]  = A;
  DATA_TYPE (*restrict C4_)[np]     = C4;

  /* Initialize A.
   *
   * Original formula:
   *   A[i][j][k] = ((i*j + k) % np) / np;
   *
   * We compute:
   *   base = (i*j) % np;
   *   v_0 = base;
   *   v_{k+1} = (v_k + 1) mod np;
   * Then v_k = (base + k) % np = ((i*j + k) % np).
   */
  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++) {
      int ij_mod = (i * j) % np;
      int v = ij_mod;
      for (k = 0; k < np; k++) {
        A_[i][j][k] = (DATA_TYPE)v / np;
        v++;
        if (v == np)
          v = 0; /* wrap around instead of using % each time */
      }
    }

  /* Initialize C4.
   *
   * Original formula:
   *   C4[i][j] = (i*j % np) / np;
   *
   * For fixed i, (i*j) % np evolves as:
   *   v_0 = 0;
   *   v_{j+1} = (v_j + i) mod np;
   * So v_j = (i*j) % np.
   */
  for (i = 0; i < np; i++) {
    int v = 0;
    for (j = 0; j < np; j++) {
      C4_[i][j] = (DATA_TYPE)v / np;
      v += i;
      if (v >= np)
        v -= np; /* since 0 <= i < np, v < 2*np, one subtraction is enough */
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nr, int nq, int np,
		 DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np))
{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++) {
	if ((i*nq*np+j*np+k) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Original computation (per (r, q)):
 *   for p:
 *     sum[p] = 0;
 *     for s:
 *       sum[p] += A[r][q][s] * C4[s][p];
 *   for p:
 *     A[r][q][p] = sum[p];
 *
 * This performs a matrix-vector product:
 *   A[r][q][:] = A[r][q][:] * C4
 * where A[r][q][:] is a row vector (1 x NP) and C4 is NP x NP.
 *
 * Optimizations:
 *  - Reorder loops to improve data reuse:
 *      * Iterate over s outermost and p innermost so that:
 *          - A[r][q][s] is loaded once per s and reused for all p.
 *          - C4[s][p] is accessed as a contiguous row.
 *      * Accumulate into a temporary 1D buffer (sum_local) for all p.
 *    This changes the arithmetic order but yields the same result.
 *
 *  - Use restrict-qualified local pointers to help the compiler
 *    generate better vectorized code.
 *
 *  - Optionally exploit parallelism over (r, q) with OpenMP
 *    (if compiled with -fopenmp). Without OpenMP, pragmas are ignored
 *    and execution is sequential but still optimized.
 *
 *  - Preserve the final content of the 'sum' array as in the original
 *    sequential code: after the kernel, 'sum' holds the result for
 *    the last (r, q) pair (r = NR-1, q = NQ-1).
 */
void kernel_doitgen[[gnu::flatten, gnu::noinline]](int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

  /* Local restrict-qualified views of the arrays.
   * Their shapes are defined using runtime sizes (nr, nq, np) so
   * they match the allocations in main().
   */
  DATA_TYPE (*restrict A_)[nq][np] = A;
  DATA_TYPE (*restrict C4_)[np]    = C4;
  DATA_TYPE *restrict sum_global   = sum;

#pragma scop
  /* Parallelize over the outer (r, q) loops when OpenMP is enabled.
   * - 'collapse(2)' exposes more parallelism by treating (r,q) pairs
   *   as a single 2D iteration space.
   * - Each (r, q) iteration uses its own stack-allocated sum_local,
   *   so there are no data races.
   *
   * When compiled without -fopenmp, this pragma is ignored and the
   * code executes sequentially.
   */
#pragma omp parallel for collapse(2) private(p, s) default(none) \
  shared(A_, C4_, sum_global, nr, nq, np) if (_PB_NR * _PB_NQ > 1)
  for (r = 0; r < _PB_NR; r++)
    for (q = 0; q < _PB_NQ; q++) {

      /* Temporary buffer holding the result for this (r, q).
       * Using a stack-allocated array improves locality and avoids
       * false sharing between threads.
       */
      DATA_TYPE sum_local[_PB_NP];

      /* Initialize sum_local to zero (vectorizable). */
      for (p = 0; p < _PB_NP; p++)
        sum_local[p] = SCALAR_VAL(0.0);

      /* Pointer to the current A[r][q][:] row for fast access. */
      DATA_TYPE *restrict A_row = &A_[r][q][0];

      /* Optimized loop nest:
       *  - 's' iterates over the input vector A_row.
       *  - For each s, we multiply A_row[s] by the entire row C4_[s][:]
       *    and accumulate into sum_local[:].
       *
       * This ensures:
       *  - A_row is read sequentially.
       *  - C4 is read row-by-row (contiguous in memory).
       *  - sum_local is updated sequentially.
       */
      for (s = 0; s < _PB_NP; s++) {
        DATA_TYPE a_rs = A_row[s];
        DATA_TYPE *restrict C4_row = &C4_[s][0];

        for (p = 0; p < _PB_NP; p++) {
          sum_local[p] += a_rs * C4_row[p];
        }
      }

      /* Write back the computed row into A. */
      for (p = 0; p < _PB_NP; p++)
        A_[r][q][p] = sum_local[p];

      /* Preserve the observable behavior of the original code
       * with respect to the 'sum' array: after all iterations,
       * 'sum' contains the result corresponding to the last
       * (r, q) pair (r = _PB_NR - 1, q = _PB_NQ - 1).
       *
       * Exactly one (r, q) pair satisfies this condition, so this
       * write has no data races even under OpenMP.
       */
      if (r == _PB_NR - 1 && q == _PB_NQ - 1) {
        for (p = 0; p < _PB_NP; p++)
          sum_global[p] = sum_local[p];
      }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int nr = NR;
  int nq = NQ;
  int np = NP;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A,DATA_TYPE,NR,NQ,NP,nr,nq,np);
  POLYBENCH_1D_ARRAY_DECL(sum,DATA_TYPE,NP,np);
  POLYBENCH_2D_ARRAY_DECL(C4,DATA_TYPE,NP,NP,np,np);

