  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied (while preserving original results):
   - Reordered the inner loops to improve data locality:
       * A[r][q][s] is now loaded once per s and reused across all p.
       * C4 is traversed along its innermost (row-major) dimension.
   - Introduced a thread-private temporary vector (sum_local) so that
     the outer (r, q) loops can be parallelized safely with OpenMP.
   - Added an explicit final write to 'sum' to match the observable
     final state of the original sequential kernel.
*/
void kernel_doitgen[[gnu::flatten, gnu::noinline]](int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

  /* Local copies of loop bounds (helps some compilers). */
  const int r_bound = _PB_NR;
  const int q_bound = _PB_NQ;
  const int p_bound = _PB_NP;

#pragma scop
  /* Each (r, q) pair operates on a distinct row of A and only reads C4.
     The computation for different (r, q) is therefore independent and
     can be parallelized. */
#pragma omp parallel for collapse(2) private(p, s) if (r_bound * q_bound >= 32)
  for (r = 0; r < r_bound; r++)
    for (q = 0; q < q_bound; q++)
    {
      /* Thread-private accumulation buffer.
         Guard the VLA size so it is always >= 1 (avoids zero-length VLAs
         if p_bound happens to be 0). */
      const int np_eff = (p_bound > 0) ? p_bound : 1;
      DATA_TYPE sum_local[np_eff];

      /* Initialize accumulation vector once per (r, q). */
      for (p = 0; p < p_bound; p++)
        sum_local[p] = SCALAR_VAL(0.0);

      /* Original computation:
           for (p)
             sum[p] = 0;
             for (s)
               sum[p] += A[r][q][s] * C4[s][p];

         Reordered for better locality:
           for (s)
             a_val = A[r][q][s];
             for (p)
               sum_local[p] += a_val * C4[s][p];

         For each fixed p, the sequence of additions over s is identical,
         so floating-point results are bitwise identical to the original. */
      for (s = 0; s < p_bound; s++)
      {
        const DATA_TYPE a_val = A[r][q][s];
        const DATA_TYPE *c4_row = &C4[s][0];

        /* Innermost loop is a simple AXPY-like operation and is
           amenable to vectorization. The OpenMP 'simd' pragma is
           ignored when OpenMP is not enabled, but can improve
           auto-vectorization under -fopenmp / -fopenmp-simd. */
#pragma omp simd
        for (p = 0; p < p_bound; p++)
          sum_local[p] += a_val * c4_row[p];
      }

      /* Write the updated row back to A. */
      for (p = 0; p < p_bound; p++)
        A[r][q][p] = sum_local[p];
    }
#pragma endscop

  /* Restore the observable final state of 'sum'.
     In the original sequential kernel, after all iterations complete,
     'sum[p]' contains the last updated row A[nr-1][nq-1][p].  We
     recompute that relation here in a race-free manner. */
  if (r_bound > 0 && q_bound > 0)
  {
    const int r_last = r_bound - 1;
    const int q_last = q_bound - 1;
    for (p = 0; p < p_bound; p++)
      sum[p] = A[r_last][q_last][p];
  }
}


int main(int argc, char** argv)
{
