  /* Precompute reciprocal of np in the working floating type. */
  const DATA_TYPE inv_np = (DATA_TYPE)1.0 / (DATA_TYPE)np;

  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++) {
      int ij = i * j;
      for (k = 0; k < np; k++) {
        int t = (ij + k) % np;
	A[i][j][k] = (DATA_TYPE)t * inv_np;
      }
    }

  for (i = 0; i < np; i++)
    for (j = 0; j < np; j++) {
      int t = (i * j) % np;
      C4[i][j] = (DATA_TYPE)t * inv_np;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nr, int nq, int np,
		 DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np))
{
