  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++) {
	if ((i*nq*np+j*np+k) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use local restrict-qualified aliases for better alias analysis.
   - Reorder loops so that we accumulate over 's' and traverse rows of C4
     contiguously, reusing A[r][q][s] once per s instead of once per (p,s).
   - Use a per-(r,q) temporary buffer sum_local[] on the stack to improve
     cache locality and enable vectorization.
   - Add OpenMP parallelization over (r,q); when compiled without OpenMP
     support, the pragmas are ignored and the code remains sequential.
   - Reconstruct the contents of 'sum' after the transformed computation
     so the externally visible behavior matches the original kernel.
*/
void kernel_doitgen[[gnu::flatten, gnu::noinline]](int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

  /* Local restrict-qualified aliases to help the compiler optimize.
     In the PolyBench setting these arrays are allocated disjointly,
     so the non-aliasing assumption holds. */
  DATA_TYPE (*restrict A_)[nq][np] = (DATA_TYPE (*restrict)[nq][np]) A;
  DATA_TYPE (*restrict C4_)[np]    = (DATA_TYPE (*restrict)[np]) C4;
  DATA_TYPE *restrict sum_         = (DATA_TYPE *restrict) sum;

#pragma scop
  /* The (r,q) iterations are independent and can be parallelized.
     Each iteration uses its own private accumulation buffer. */
#pragma omp parallel for collapse(2) schedule(static) if(_PB_NR*_PB_NQ > 1)
  for (r = 0; r < _PB_NR; r++)
    for (q = 0; q < _PB_NQ; q++) {

      /* Per-(r,q) accumulation buffer.
         Stack allocation keeps it close to the cores and avoids
         false sharing between threads. */
      DATA_TYPE sum_local[_PB_NP];

      /* Initialize all partial sums once. This replaces the original
         "initialize inside the p-loop" with an equivalent but more
         cache- and vectorization-friendly form. */
#pragma omp simd
      for (p = 0; p < _PB_NP; p++)
        sum_local[p] = SCALAR_VAL(0.0);

      /* Compute:
           sum_local[p] = sum_s A[r][q][s] * C4[s][p]
         Loop order (s, p) improves data reuse:
           - A[r][q][s] is loaded once per s and reused across all p.
           - C4 is accessed row-wise (s fixed, p varying), which is
             contiguous in memory for row-major layout. */
      for (s = 0; s < _PB_NP; s++) {
        DATA_TYPE a_val = A_[r][q][s];
        DATA_TYPE const * restrict C4_row = C4_[s];

#pragma omp simd
        for (p = 0; p < _PB_NP; p++)
          sum_local[p] += a_val * C4_row[p];
      }

      /* Write the result back to A. */
#pragma omp simd
      for (p = 0; p < _PB_NP; p++)
        A_[r][q][p] = sum_local[p];
    }
