     execute (r,q) iterations in parallel), we explicitly reconstruct
     that final state here to preserve the observable behavior. */
  if (_PB_NR > 0 && _PB_NQ > 0 && _PB_NP > 0) {
    int last_r = _PB_NR - 1;
    int last_q = _PB_NQ - 1;

    for (p = 0; p < _PB_NP; p++)
      sum_[p] = A_[last_r][last_q][p];
  }
}


